output_text:
[
  {
    "id": "no_carts_single_file_aisles",
    "text": "Shopping carts are prohibited in single-file shelf aisles where shelves flank both sides.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "do_not_enter_single_file_with_cart",
    "text": "An agent must not push a cart from a wider aisle into a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "MOVE",
              "hasCart",
              {
                "not": "singleFileShelfAisle"
              }
            ]
          },
          "post": {
            "and": [
              "hasCart",
              "singleFileShelfAisle"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "narrow_shelf_shopping_on_foot",
    "text": "Items in single-file shelf aisles should be collected only while the shopper is on foot, not while holding a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            {
              "or": [
                "shelfE",
                "shelfW"
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "singleFileShelfAisle",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "retrieve_parked_cart",
    "text": "After parking a cart at the mouth of a narrow aisle, the shopper is obliged to return and pick it up again.",
    "abstraction": {
      "state_properties": {
        "aisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "parkCartAtMouth": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart",
              "aisleMouth"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "pickUpCartAtMouth": {
          "pre": {
            "and": [
              "INTERACT",
              {
                "not": "hasCart"
              },
              "aisleMouth"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCartAtMouth",
      "discharge": "pickUpCartAtMouth"
    }
  },
  {
    "id": "park_only_at_aisle_mouths",
    "text": "Carts may be put down only at designated aisle-mouth parking spots, not arbitrarily in the store.",
    "abstraction": {
      "state_properties": {
        "aisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "approvedCartParking": "aisleMouth"
      },
      "events": {
        "putDownCart": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "putDownCart",
          {
            "not": "approvedCartParking"
          }
        ]
      }
    }
  },
  {
    "id": "no_unaccompanied_wide_aisle_travel",
    "text": "A shopper without a cart may move only within narrow pedestrian shopping aisles or at their mouths.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            {
              "or": [
                "shelfE",
                "shelfW"
              ]
            }
          ]
        },
        "aisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "onFootShoppingZone": {
          "or": [
            "singleFileShelfAisle",
            "aisleMouth"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          {
            "not": "onFootShoppingZone"
          }
        ]
      }
    }
  },
  {
    "id": "non_cart_interactions_only_at_shelves",
    "text": "Any interaction that is not picking up or putting down a cart must occur next to a shelf.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "pickUpCart": {
          "pre": {
            "and": [
              "INTERACT",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "hasCart"
        },
        "putDownCart": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          {
            "not": "adjShelf"
          },
          {
            "not": "pickUpCart"
          },
          {
            "not": "putDownCart"
          }
        ]
      }
    }
  },
  {
    "id": "wide_shelf_items_need_cart",
    "text": "When interacting with shelves from a wide aisle, the shopper must have the cart with them.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            {
              "or": [
                "shelfE",
                "shelfW"
              ]
            }
          ]
        },
        "wideShelfFace": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileShelfAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "wideShelfFace",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  }
]
